        ["Empty: the global tool. Or a coworkee executable, or Coworkee.Cli.dll of a local build (runs with dotnet)."] = "Vide : l'outil global. Ou un exécutable coworkee, ou le Coworkee.Cli.dll d'un build local (lancé avec dotnet).",
        ["Template source"] = "Source du modèle",
        ["A Coworkee.Templates .nupkg or folder instead of nuget.org (coworkee new --template-source), for local builds."] = "Un .nupkg ou dossier Coworkee.Templates au lieu de nuget.org (coworkee new --template-source), pour les builds locaux.",
        ["Local package feed"] = "Flux de paquets local",
