        // option catalog of the CLI
        ["Display title in the browser, the app bar, the sign-in pages and the Aspire dashboard (default: the name)."] = "Titre affiché dans le navigateur, la barre de l'app, les pages de connexion et le tableau de bord Aspire (par défaut : le nom).",
