        ["The app is not set up yet: its setup page asks for this token."] = "L'app n'est pas encore configurée : sa page de configuration demande ce jeton.",
        ["Neutral grays and blue, like a code hosting site."] = "Gris neutres et bleu, comme un site d'hébergement de code.",
        ["Editor look: compact, dark gray with blue."] = "Style éditeur : compact, gris foncé avec du bleu.",
        ["Cool polar blues and frost."] = "Bleus polaires froids et givre.",
        ["Purple and pink on a night background."] = "Violet et rose sur fond de nuit.",
        ["Warm cream and deep teal, serif headings."] = "Crème chaud et bleu canard profond, titres à empattements.",
        ["Soft editor grays, blue and violet."] = "Gris doux d'éditeur, bleu et violet.",
        ["Plain white paper, serif headings, flat."] = "Papier blanc uni, titres à empattements, plat.",
        ["Aubergine app bar, green accents."] = "Barre de l'app aubergine, accents verts.",
        ["Dark header with the logo, white pages, blue links, like GitHub."] = "En-tête sombre avec le logo, pages blanches, liens bleus, comme GitHub.",
        ["Link page look: lime and violet, pill buttons, roomy."] = "Style page de liens : citron vert et violet, boutons en pilule, aéré.",
        ["Green on black like a shell, monospace, square, no logo."] = "Vert sur noir comme un shell, monospace, carré, sans logo.",
        ["Dark sidebar with the logo next to light pages, indigo."] = "Barre latérale sombre avec le logo à côté de pages claires, indigo.",
        ["Amber on charcoal, dark header with the logo."] = "Ambre sur anthracite, en-tête sombre avec le logo.",
