        ["Black and white, no shadows."] = "Noir et blanc, sans ombres.",
        ["Primary color"] = "Couleur primaire",
        ["Primary brand color #rrggbb. With a brand color the app gets its own theme (named like the title), based on the chosen theme, as default."] = "Couleur de marque primaire #rrggbb. Avec une couleur de marque, l'app reçoit par défaut son propre thème (nommé comme le titre), basé sur le thème choisi.",
