        ["Sign-in layout"] = "Mise en page de la connexion",
        ["Layout of the sign-in pages."] = "Mise en page des pages de connexion.",
        ["Split for a full-page image or video, Card for a plain look."] = "Split pour une image ou une vidéo pleine page, Carte pour un style sobre.",
        ["Changeable later on the Themes page"] = "Modifiable plus tard sur la page Thèmes",
