        [".mp4, .webm, .ogg and .mov play as video"] = ".mp4, .webm, .ogg et .mov sont lus comme vidéo",
        ["Large videos slow the first sign-in"] = "Les grosses vidéos ralentissent la première connexion",
        ["Sign-in media side"] = "Côté du média de connexion",
