        ["Mapperly for many or large entities."] = "Mapperly pour des entités nombreuses ou volumineuses.",
        ["manual: plain code you can read"] = "manual : du code simple et lisible",
        ["mapperly: compile-time mapper, reports unmapped members"] = "mapperly : mapper à la compilation, signale les membres non mappés",
        ["manual: one more line per property"] = "manual : une ligne de plus par propriété",
