        ["libreTranslate: free, no account, the texts stay on your machine"] = "libreTranslate : gratuit, sans compte, les textes restent sur ta machine",
        ["myMemory: free, no container, nothing to install"] = "myMemory : gratuit, sans conteneur, rien à installer",
        ["deepL, azure, google: high quality, free monthly quota with an account"] = "deepL, azure, google : haute qualité, quota mensuel gratuit avec un compte",
